import SwiftUI

struct SimpleNavStack: View {
    let items = ["One", "Two"]
    var body: some View {
        NavigationStack {
            List(items, id: \.self) { item in
                Text(item)
            }
            .navigationTitle("Numbers")
        }
    }
}

let stackView = SimpleNavStack()
print("SimpleNavStack created: \(type(of: stackView))")

import SwiftUI

struct DeepLinkStack: View {
    @State private var path = NavigationPath()
    var body: some View {
        NavigationStack(path: $path) {
            Button("Open Detail") {
                path.append("DetailScreen")
            }
        }
    }
}

let deepView = DeepLinkStack()
print("DeepLinkStack created: \(type(of: deepView))")
